export type SampleStatus = "passed" | "warning" | "failed";

export type Treatment = "Control" | "Low dose" | "High dose";

export type ExplorerSample = {
  id: string;
  well: string;
  treatment: Treatment;
  /** µg/mL. Null when the measurement was censored or not taken. */
  concentration: number | null;
  /** Absolute uncertainty in µg/mL. */
  uncertainty: number | null;
  /** Absorbance at 600 nm, in arbitrary units. */
  a600: number;
  status: SampleStatus;
  /** ISO 8601 timestamp. */
  collectedAt: string;
  operator: string;
  /** Concentration over 12 hours, one value every 1.5 h. */
  series: readonly number[];
  note?: string;
};

export type ExplorerFilters = {
  query: string;
  status: "all" | SampleStatus;
  treatment: "all" | Treatment;
};

export const SAMPLE_STATUSES: readonly SampleStatus[] = [
  "passed",
  "warning",
  "failed",
];

export const TREATMENTS: readonly Treatment[] = [
  "Control",
  "Low dose",
  "High dose",
];

export const STATUS_LABEL: Record<SampleStatus, string> = {
  passed: "Passed",
  warning: "Low signal",
  failed: "Censored",
};

export function isSampleStatus(value: string | null): value is SampleStatus {
  return value !== null && SAMPLE_STATUSES.includes(value as SampleStatus);
}

export function isTreatment(value: string | null): value is Treatment {
  return value !== null && TREATMENTS.includes(value as Treatment);
}

import {
  type ExplorerFilters,
  type ExplorerSample,
  STATUS_LABEL,
} from "./types";

export function filterSamples(
  samples: readonly ExplorerSample[],
  filters: ExplorerFilters,
): ExplorerSample[] {
  const term = filters.query.trim().toLowerCase();
  return samples.filter((sample) => {
    if (filters.status !== "all" && sample.status !== filters.status) {
      return false;
    }
    if (filters.treatment !== "all" && sample.treatment !== filters.treatment) {
      return false;
    }
    if (!term) {
      return true;
    }
    const haystack = [
      sample.id,
      sample.well,
      sample.treatment,
      sample.operator,
      STATUS_LABEL[sample.status],
    ]
      .join(" ")
      .toLowerCase();
    return haystack.includes(term);
  });
}

export type SampleSummary = {
  count: number;
  passed: number;
  flagged: number;
  missing: number;
  /** Median concentration, excluding missing values. Null when nothing is left. */
  median: number | null;
};

export function summarize(samples: readonly ExplorerSample[]): SampleSummary {
  const concentrations = samples
    .map((sample) => sample.concentration)
    .filter((value): value is number => value !== null)
    .sort((a, b) => a - b);

  return {
    count: samples.length,
    passed: samples.filter((sample) => sample.status === "passed").length,
    flagged: samples.filter((sample) => sample.status !== "passed").length,
    missing: samples.length - concentrations.length,
    median:
      concentrations.length === 0
        ? null
        : concentrations.length % 2 === 1
          ? concentrations[Math.floor(concentrations.length / 2)]
          : (concentrations[concentrations.length / 2 - 1] +
              concentrations[concentrations.length / 2]) /
            2,
  };
}

const DATE_FORMATTER = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

const DATE_TIME_FORMATTER = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  hourCycle: "h23",
  timeZone: "UTC",
});

export function formatDate(iso: string): string {
  return DATE_FORMATTER.format(new Date(iso));
}

export function formatDateTime(iso: string): string {
  return `${DATE_TIME_FORMATTER.format(new Date(iso))} UTC`;
}

export function formatDateRange(values: readonly string[]): string {
  if (values.length === 0) {
    return "—";
  }
  const times = values
    .map((value) => Date.parse(value))
    .filter(Number.isFinite);
  if (times.length === 0) {
    return "—";
  }
  const first = new Date(Math.min(...times)).toISOString();
  const last = new Date(Math.max(...times)).toISOString();
  return first.slice(0, 10) === last.slice(0, 10)
    ? formatDate(first)
    : `${formatDate(first)} – ${formatDate(last)}`;
}

function cell(value: string | number | null): string {
  if (value === null) {
    return "";
  }
  const text = String(value);
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

const CSV_HEADER = [
  "sample_id",
  "well",
  "treatment",
  "concentration_ug_ml",
  "uncertainty_ug_ml",
  "a600_au",
  "status",
  "collected_at",
  "operator",
  "note",
].join(",");

export function toCsv(samples: readonly ExplorerSample[]): string {
  const rows = samples.map((sample) =>
    [
      sample.id,
      sample.well,
      sample.treatment,
      sample.concentration,
      sample.uncertainty,
      sample.a600,
      sample.status,
      sample.collectedAt,
      sample.operator,
      sample.note ?? "",
    ]
      .map(cell)
      .join(","),
  );
  return [CSV_HEADER, ...rows].join("\n");
}

"use client";

import type * as React from "react";
import { Button } from "@/registry/default/ui/button";
import { Input } from "@/registry/default/ui/input";
import {
  type ExplorerFilters,
  SAMPLE_STATUSES,
  STATUS_LABEL,
  TREATMENTS,
} from "./types";

export type FilterRailProps = {
  filters: ExplorerFilters;
  onChange: (patch: Partial<ExplorerFilters>) => void;
  onReset: () => void;
  activeCount: number;
  statusCounts: Record<"all" | (typeof SAMPLE_STATUSES)[number], number>;
  treatmentCounts: Record<"all" | (typeof TREATMENTS)[number], number>;
};

export function FilterRail({
  filters,
  onChange,
  onReset,
  activeCount,
  statusCounts,
  treatmentCounts,
}: FilterRailProps): React.ReactElement {
  return (
    <aside
      aria-label="Filters"
      className="grid content-start gap-4 border-b p-3 lg:border-e lg:border-b-0 print:hidden"
      data-slot="data-explorer-filters"
    >
      <div className="flex items-center justify-between gap-2">
        <h2 className="font-medium text-sm">Filters</h2>
        <Button
          disabled={activeCount === 0}
          onClick={onReset}
          size="xs"
          type="button"
          variant="ghost"
        >
          Reset
        </Button>
      </div>

      <Input
        aria-label="Filter samples"
        onChange={(event) => onChange({ query: event.target.value })}
        placeholder="Sample, well, operator…"
        size="sm"
        type="search"
        value={filters.query}
      />

      <fieldset className="min-w-0">
        <legend className="mb-1.5 font-medium text-muted-foreground text-xs">
          Status
        </legend>
        <div className="flex flex-wrap gap-1 lg:grid">
          <FilterButton
            active={filters.status === "all"}
            count={statusCounts.all}
            label="All"
            onClick={() => onChange({ status: "all" })}
          />
          {SAMPLE_STATUSES.map((status) => (
            <FilterButton
              active={filters.status === status}
              count={statusCounts[status]}
              key={status}
              label={STATUS_LABEL[status]}
              onClick={() => onChange({ status })}
            />
          ))}
        </div>
      </fieldset>

      <fieldset className="min-w-0">
        <legend className="mb-1.5 font-medium text-muted-foreground text-xs">
          Treatment
        </legend>
        <div className="flex flex-wrap gap-1 lg:grid">
          <FilterButton
            active={filters.treatment === "all"}
            count={treatmentCounts.all}
            label="All"
            onClick={() => onChange({ treatment: "all" })}
          />
          {TREATMENTS.map((treatment) => (
            <FilterButton
              active={filters.treatment === treatment}
              count={treatmentCounts[treatment]}
              key={treatment}
              label={treatment}
              onClick={() => onChange({ treatment })}
            />
          ))}
        </div>
      </fieldset>

      <p className="hidden text-muted-foreground text-xs leading-relaxed lg:block">
        Filters, sort, and the open sample are kept in the URL. Share the
        address to reproduce this view.
      </p>
    </aside>
  );
}

function FilterButton({
  label,
  count,
  active,
  onClick,
}: {
  label: string;
  count: number;
  active: boolean;
  onClick: () => void;
}): React.ReactElement {
  return (
    <Button
      aria-pressed={active}
      className="justify-between gap-3 lg:w-full"
      onClick={onClick}
      size="xs"
      type="button"
      variant={active ? "secondary" : "ghost"}
    >
      <span className="truncate">{label}</span>
      <span className="font-mono text-muted-foreground text-xs tabular-nums">
        {count}
      </span>
    </Button>
  );
}

"use client";

import { InboxIcon } from "lucide-react";
import type * as React from "react";
import { ScientificNumber } from "@/registry/default/instruments/scientific-number";
import { Sparkline } from "@/registry/default/instruments/sparkline";
import {
  type Status,
  StatusBadge,
} from "@/registry/default/instruments/status-badge";
import {
  Timeline,
  type TimelineItem,
} from "@/registry/default/instruments/timeline";
import { Separator } from "@/registry/default/ui/separator";
import { formatDateTime } from "./adapter";
import { type ExplorerSample, type SampleStatus, STATUS_LABEL } from "./types";

const STATUS: Record<SampleStatus, Status> = {
  passed: "success",
  warning: "warning",
  failed: "error",
};

function minutesAfter(iso: string, minutes: number): string {
  return new Date(Date.parse(iso) + minutes * 60_000).toISOString();
}

function custody(sample: ExplorerSample): TimelineItem[] {
  return [
    {
      id: "collected",
      title: "Collected",
      description: "Sample logged at the bench.",
      time: formatDateTime(sample.collectedAt),
      dateTime: sample.collectedAt,
      meta: sample.operator,
    },
    {
      id: "acquired",
      title: "Absorbance read",
      description: "A₆₀₀ measured at 600 nm.",
      time: formatDateTime(minutesAfter(sample.collectedAt, 18)),
      dateTime: minutesAfter(sample.collectedAt, 18),
      status: "success",
      meta: "BMG FLUOstar",
    },
    {
      id: "reviewed",
      title:
        sample.status === "passed" ? "QC reviewed" : "QC flagged for re-run",
      description:
        sample.status === "passed"
          ? "Within the assay’s acceptance window."
          : "See the sample note before using this value.",
      time: formatDateTime(minutesAfter(sample.collectedAt, 42)),
      dateTime: minutesAfter(sample.collectedAt, 42),
      status: STATUS[sample.status],
      meta: "A. Rao",
    },
  ];
}

export function SampleInspector({
  sample,
}: {
  sample: ExplorerSample | null;
}): React.ReactElement {
  if (!sample) {
    return (
      <div
        className="flex h-full min-h-48 flex-col items-center justify-center gap-2 p-6 text-center"
        data-slot="sample-inspector-empty"
      >
        <InboxIcon
          aria-hidden="true"
          className="size-5 text-muted-foreground"
        />
        <p className="font-medium text-sm">No sample selected</p>
        <p className="max-w-52 text-muted-foreground text-xs leading-relaxed">
          Choose a row to see its measurement, series, and chain of custody.
        </p>
      </div>
    );
  }

  return (
    <div className="grid gap-4" data-slot="sample-inspector">
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="font-mono text-muted-foreground text-xs">
            {sample.well} · {sample.id}
          </p>
          <h2 className="truncate font-heading font-semibold text-lg">
            {sample.treatment}
          </h2>
        </div>
        <StatusBadge
          label={STATUS_LABEL[sample.status]}
          status={STATUS[sample.status]}
        />
      </div>

      <dl className="grid gap-2 text-xs">
        <DetailRow
          label="Concentration"
          value={
            sample.concentration === null ? (
              <span className="text-muted-foreground">—</span>
            ) : (
              <ScientificNumber
                precision={1}
                uncertainty={sample.uncertainty ?? undefined}
                unit="µg/mL"
                value={sample.concentration}
              />
            )
          }
        />
        <DetailRow
          label="A₆₀₀"
          value={
            <ScientificNumber precision={2} unit="AU" value={sample.a600} />
          }
        />
        <DetailRow
          label="Collected"
          value={formatDateTime(sample.collectedAt)}
        />
        <DetailRow label="Operator" value={sample.operator} />
      </dl>

      {sample.note ? (
        <p className="rounded-lg border border-dashed px-2.5 py-2 text-muted-foreground text-xs leading-relaxed">
          {sample.note}
        </p>
      ) : null}

      <Separator />

      <div>
        <div className="flex items-baseline justify-between gap-2">
          <h3 className="font-medium text-sm">12 h series</h3>
          <span className="font-mono text-muted-foreground text-xs">µg/mL</span>
        </div>
        <Sparkline
          className="mt-2 h-14 w-full"
          formatValue={(value) => `${value.toFixed(1)} µg/mL`}
          label={`${sample.id} concentration over 12 hours`}
          showLast
          values={sample.series}
        />
        <div className="mt-1 flex justify-between font-mono text-[10px] text-muted-foreground">
          <span>0 h</span>
          <span>6 h</span>
          <span>12 h</span>
        </div>
      </div>

      <Separator />

      <div>
        <h3 className="mb-3 font-medium text-sm">Chain of custody</h3>
        <Timeline items={custody(sample)} label={`Events for ${sample.id}`} />
      </div>
    </div>
  );
}

function DetailRow({
  label,
  value,
}: {
  label: string;
  value: React.ReactNode;
}): React.ReactElement {
  return (
    <div className="flex items-baseline justify-between gap-4">
      <dt className="shrink-0 text-muted-foreground">{label}</dt>
      <dd className="min-w-0 text-end tabular-nums">{value}</dd>
    </div>
  );
}

"use client";

import {
  AlertTriangleIcon,
  DownloadIcon,
  LockIcon,
  PrinterIcon,
  RefreshCwIcon,
  WifiOffIcon,
} from "lucide-react";
import * as React from "react";
import {
  DataTable,
  type DataTableColumn,
} from "@/registry/default/instruments/data-table";
import { ScientificNumber } from "@/registry/default/instruments/scientific-number";
import { Stat, StatGrid } from "@/registry/default/instruments/stat";
