      <ScientificNumber className="text-xs" precision={2} value={row.a600} />
    ),
    sortValue: (row) => row.a600,
  },
  {
    id: "status",
    header: "QC",
    className: "hidden sm:table-cell",
    cell: (row) => (
      <StatusBadge
        label={STATUS_LABEL[row.status]}
